    npg = tl.num_programs(0)
    ar = tl.arange(0, TILE)
    step = npg * TILE
    off_cur = pid * TILE
    o = off_cur + ar
    x_cur = tl.load(x_ptr + o, mask=o < numel)
    off_next = off_cur + step
    for _ in range(pid + npg, num_tiles, npg):
        on = off_next + ar
        x_next = tl.load(x_ptr + on, mask=on < numel)
        oc = off_cur + ar
        r = libdevice.acos(x_cur.to(tl.float32))
        tl.store(x_ptr + oc, r.to(x_cur.dtype), mask=oc < numel)
        x_cur = x_next
        off_cur = off_next
        off_next = off_next + step
